public class Query {
    public static record Match(EGamaObject object, EGamaModel model) {}

    public Set<Match> objectsWithModel(Resource resource) {
        Set<Match> result = new HashSet<>();

        for (EObject root : resource.getContents()) {
            collectObjectsWithModel(root, result);
        }

        return result;
    }

    private void collectObjectsWithModel(EObject eObject, Set<Match> result) {
        if (eObject instanceof EGamaObject o) {
            EGamaModel m = o.getModel();
            if (m != null) {
                result.add(new Match(o, m));
            }
        }

        for (EObject child : eObject.eContents()) {
            collectObjectsWithModel(child, result);
        }
    }
}

