public class Query {
    public static record Match(PROPERTYPATH pp, List<PROPERTYELM> firstPropertyEls) {}

    public Set<Match> propertyPathsWithFirstElm(Resource resource) {
        Set<Match> result = new HashSet<>();

        for (EObject root : resource.getContents()) {
            collectPPWithFirstElm(root, result);
        }

        return result;
    }

    private void collectPPWithFirstElm(EObject eObject, Set<Match> result) {
        if (eObject instanceof PROPERTYPATH pp) {
            List<PROPERTYELM> list = new ArrayList<>(pp.getPropertys());
            if (!list.isEmpty()) {
                // take first element (list as propertys[0..*])
                result.add(new Match(pp, List.of(list.get(0))));
            }
        }

        for (EObject child : eObject.eContents()) {
            collectPPWithFirstElm(child, result);
        }
    }
}

