    public Set<EGamaLink> objectToObjectLinks(Resource resource) {
        Set<EGamaLink> result = new HashSet<>();

        for (EObject root : resource.getContents()) {
            collectLinks(root, result);
        }

        return result;
    }

    private void collectLinks(EObject eObject, Set<EGamaLink> result) {
        if (eObject instanceof EGamaLink gl) {
            if (gl.getSource() instanceof EGamaObject && gl.getTarget() instanceof EGamaObject) {
                result.add(gl);
            }
        }

        for (EObject child : eObject.eContents()) {
            collectLinks(child, result);
        }
    }
}

